import{_ as t,o as e,c as n,a2 as s}from"./chunks/framework.CHeM0PsO.js";const u=JSON.parse('{"title":"端点","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/concepts/endpoints.md","filePath":"zh-CN/concepts/endpoints.md","lastUpdated":1784903584000}'),o={name:"zh-CN/concepts/endpoints.md"};function d(p,a,i,r,c,l){return e(),n("div",null,[...a[0]||(a[0]=[s(`<h1 id="端点" tabindex="-1">端点 <a class="header-anchor" href="#端点" aria-label="Permalink to &quot;端点&quot;">​</a></h1><p>端点是特定的 HTTP 方法 + 路径，可以被调用（例如 <code>GET /api/users/{id}</code>）。端点是 LLM 发现、检查和调用的实际 API 操作。</p><h2 id="结构" tabindex="-1">结构 <a class="header-anchor" href="#结构" aria-label="Permalink to &quot;结构&quot;">​</a></h2><p>每个端点包含：</p><ul><li><strong>HTTP 方法</strong>：GET、POST、PUT、PATCH、DELETE、HEAD、OPTIONS</li><li><strong>路径</strong>：<code>/api/v1/users/{id}</code></li><li><strong>摘要</strong>：端点功能的简短描述 — 对 LLM 快速理解其用途非常有用</li><li><strong>描述</strong>：端点行为、参数和用例的详细说明</li><li><strong>参数</strong>：路径、查询、头、cookie</li><li><strong>请求体</strong>：用于 POST/PUT/PATCH</li><li><strong>响应</strong>：状态码和响应模式</li></ul><p><code>summary</code> 和 <code>description</code> 字段来自 OpenAPI/Swagger/Postman 文件。它们是 LLM 理解端点功能的主要方式。编写良好的摘要使端点发现更加高效。</p><h2 id="端点的-mcp-工具" tabindex="-1">端点的 MCP 工具 <a class="header-anchor" href="#端点的-mcp-工具" aria-label="Permalink to &quot;端点的 MCP 工具&quot;">​</a></h2><table tabindex="0"><thead><tr><th>工具</th><th>描述</th></tr></thead><tbody><tr><td><code>endpoint_by_spec</code></td><td>spec 中的所有端点</td></tr><tr><td><code>endpoint_by_collection</code></td><td>collection 中的端点</td></tr><tr><td><code>endpoint_by_tag</code></td><td>标签中的端点</td></tr><tr><td><code>endpoint_by_id</code></td><td>快速端点摘要</td></tr><tr><td><code>inspect</code></td><td>完整端点详情（模式、参数）</td></tr><tr><td><code>invoke</code></td><td>调用端点</td></tr><tr><td><code>search</code></td><td>按文本搜索端点</td></tr></tbody></table><h2 id="弃用的端点" tabindex="-1">弃用的端点 <a class="header-anchor" href="#弃用的端点" aria-label="Permalink to &quot;弃用的端点&quot;">​</a></h2><p>在规范中标记为 <code>deprecated</code> 的端点在检查时会显示通知。</p><h2 id="配置" tabindex="-1">配置 <a class="header-anchor" href="#配置" aria-label="Permalink to &quot;配置&quot;">​</a></h2><p>从 swag2mcp 的角度来看，端点是<strong>只读的</strong>。端点没有 YAML 配置设置 — 你不能在 <code>swag2mcp.yaml</code> 中添加、删除、重命名或修改它们。</p><p>要更改端点（添加新端点、更新摘要、修改参数、标记为已弃用），请编辑原始的 OpenAPI/Swagger/Postman 文件并运行 <code>swag2mcp update</code> 以重新解析和重新索引。</p><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>查询：&quot;Show details for GET /pet/{petId}&quot;</span></span>
<span class="line"><span>→ inspect(endpointId: &quot;abc123...&quot;)</span></span>
<span class="line"><span>→ 结果：</span></span>
<span class="line"><span>  GET /pet/{petId}</span></span>
<span class="line"><span>  摘要：Find pet by ID</span></span>
<span class="line"><span>  描述：Returns a single pet by its ID</span></span>
<span class="line"><span>  参数：</span></span>
<span class="line"><span>    - petId (path, integer, required)</span></span>
<span class="line"><span>  响应：</span></span>
<span class="line"><span>    - 200: Pet object</span></span>
<span class="line"><span>    - 400: Error</span></span>
<span class="line"><span>    - 404: Not found</span></span></code></pre></div>`,15)])])}const g=t(o,[["render",d]]);export{u as __pageData,g as default};
